/**
 * Parses the body of the driver "dispatched" notification, e.g.
 * "Driver T712345C arriving in 23m5s. Fare: $34.63".
 * Returns undefined if the body is not a driver assignment.
 */
export const parseDriverAssignment = (body: string): DriverAssignment | undefined => {
