import {useCallback, useEffect, useRef, useState} from "react";
import {apiGet, apiPatch, apiPost} from "../services/http.ts";
import {RideHistory, RideHistoryEntry} from "../types/rideHistory.ts";

export const useRideHistory = () => {
    const [history, setHistory] = useState<RideHistory | undefined>();
    const [failed, setFailed] = useState(false);
    // Pending/created history entries by request ID. Keeping the promise lets the
    // driver notification wait for the entry in case it arrives before the POST returns.
    const entriesRef = useRef(new Map<number, Promise<RideHistoryEntry | undefined>>());

    const refresh = useCallback(async () => {
        try {
            setHistory(await apiGet<RideHistory>('/ride-history'));
            setFailed(false);
        } catch {
            setFailed(true);
        }
    }, []);

    useEffect(() => {
        refresh();
    }, [refresh]);

    const createEntry = useCallback((requestID: number, pickupLocation: string, dropoffLocation: string, requestTime: Date) => {
        const created = apiPost<RideHistoryEntry>('/ride-history', {
            pickupLocation,
            dropoffLocation,
            requestTime: requestTime.toISOString(),
        }, {})
            .then(entry => {
                refresh();
                return entry;
            })
            .catch(() => undefined);
        entriesRef.current.set(requestID, created);
        return created;
    }, [refresh]);

    const assignDriver = useCallback(async (requestID: number, driverPlate: string, fare: number) => {
        const created = entriesRef.current.get(requestID);
        if (!created) return;
        entriesRef.current.delete(requestID);

        const entry = await created;
        if (!entry) return;
        try {
            await apiPatch<RideHistoryEntry>('/ride-history', {id: entry.id, driverPlate, fare});
        } catch {
            // the history is informational, the ride itself is not affected
        }
        refresh();
    }, [refresh]);

    return {history, failed, createEntry, assignDriver};
};
