	"github.com/signadot/hotrod/pkg/config"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/delay"
	"github.com/signadot/hotrod/pkg/log"
)

type driverStore struct {
	errorSimulator
	tracer trace.Tracer
	logger log.Factory
}

func newDriverStore(tracer trace.Tracer, logger log.Factory) *driverStore {
	return &driverStore{
		tracer: tracer,
		logger: logger,
		errorSimulator: errorSimulator{
			errorFreq: config.GetDriverStoreErrorFreq(),
		},
	}
}

// FindDriverIDs finds IDs of drivers who are near the location.
func (s *driverStore) FindDriverIDs(ctx context.Context) []string {
	ctx, span := s.tracer.Start(ctx, "FindDriverIDs", trace.WithSpanKind(trace.SpanKindClient))
	defer span.End()

	// simulate delay
	delay.Sleep(config.GetDriverStoreFindDelay(), config.GetDriverStoreFindStdDev())

	drivers := make([]string, 10)
	for i := range drivers {
		// #nosec
		drivers[i] = fmt.Sprintf("%sT7%05dC%s",
			config.GetDriverIDPrefix(), rand.Int()%100000, config.GetDriverIDSuffix())
	}
	s.logger.For(ctx).Info("Found drivers", zap.Strings("drivers", drivers))
	return drivers
}

func (s *driverStore) GetDriversLocation(ctx context.Context, driverIDs []string) ([]*Driver, error) {
	ctx, span := s.tracer.Start(ctx, "GetDriversLocation", trace.WithSpanKind(trace.SpanKindClient))
	defer span.End()

	drivers := make([]*Driver, len(driverIDs))
	for i, driverID := range driverIDs {
		var drv Driver
		var err error
		for i := 0; i < 3; i++ {
			drv, err = s.GetDriver(ctx, driverID)
			if err == nil {
				break
)

func GetSyncProducer(clientID string, provider trace.TracerProvider) (sarama.SyncProducer, error) {
	conf := getConfig(clientID)
	conf.Producer.Partitioner = sarama.NewRandomPartitioner
	conf.Producer.RequiredAcks = sarama.WaitForAll
	conf.Producer.Retry.Max = 10 // Retry up to 10 times to produce the message
	conf.Producer.Return.Successes = true

	producer, err := sarama.NewSyncProducer(config.GetKafkaBrokers(), conf)
	if err != nil {
		return nil, err
	}

	producer = otelsarama.WrapSyncProducer(conf,
		producer,
		otelsarama.WithTracerProvider(provider),
	)
	return producer, nil
}

func GetConsumerGroup(clientID, groupID string, provider trace.TracerProvider,
	handler sarama.ConsumerGroupHandler) (sarama.ConsumerGroup, sarama.ConsumerGroupHandler, error) {
	conf := getConfig(clientID)

	consumerGroup, err := sarama.NewConsumerGroup(
		config.GetKafkaBrokers(),
		config.SignadotConsumerGroup(groupID),
		conf)
	if err != nil {
		return nil, nil, fmt.Errorf("error creating consumer group client: %v", err)
	}

	instrumentedHandler := otelsarama.WrapConsumerGroupHandler(
		handler,
		otelsarama.WithTracerProvider(provider),
	)
	return consumerGroup, instrumentedHandler, nil
}

func getConfig(clientID string) *sarama.Config {
	conf := sarama.NewConfig()
	conf.ClientID = clientID
	conf.Version = sarama.V1_1_0_0
	conf.Net.TLS.Enable = false
	conf.Net.SASL.Enable = false

