func (srv) WatchWorkloadRoutingRules(_ *routesapi.WorkloadRoutingRulesRequest, s routesapi.Routes_WatchWorkloadRoutingRulesServer) error {
	if err := s.Send(&routesapi.WorkloadRoutingRuleOp{Op: routesapi.WatchOp_SYNCED}); err != nil {
		return err
	}
	<-s.Context().Done()
	return nil
}

